// ***************
// Filename: pwm_regs.sv
// Author: FPGA Cores 4 U
// Description: Register map of pwm: its AXI4-Lite register slave
//   (axi4_lite_slave front end) with every register of the block, the ID
//   block first; the registers go to pwm's logic on named ports, its status
//   comes back on input ports. PWM timer: control, period, prescaler, dead
//   time, output inversion, duty per channel. Generated by
//   ip/scripts/regmap_gen.py from pwm_regs.json: edit the JSON and regenerate
//   (the IP_VERSION / IP_DATE stamps are kept).
//   Register map (ADDR_W = 8, byte offsets):
//     0x00 ID          RO   "PWMT" IP identifier, 4 ASCII characters (first
//                       in [31:24])
//     0x04 VERSION     RO   version, ASCII "d.dd" (+0.01 at every source
//                       update)
//     0x08 DATE        RO   date of the last source update, BCD mm/dd/yyyy
//                       (0xMMDDYYYY)
//     0x0C reserved    RO   0
//     0x10 CTRL        RW   control, reset 0x0
//                       [0] EN: 1: counting
//                       [1] CENTER: 1: centre aligned (up / down)
//                       [2] COMPLEMENTARY: 1: complementary outputs with dead
//                         time
//     0x14 PERIOD      RW   counter top, reset 0x63
//     0x18 PRESCALE    RW   clock cycles per count - 1, reset 0x0
//     0x1C DEADTIME    RW   dead time in clocks (complementary mode), reset
//                       0x0
//     0x20 INVERT      RW   output inversion per channel, reset 0x0
//     0x24 + 4 i DUTY [CHANNELS] RW   duty of channel n (loaded at the period
//                       start), reset 0x0
//   Access: RW read / write (byte strobes), RO read only (writes answer
//   SLVERR), W1C hardware sets / software writes 1 to clear (a set wins), W1S
//   software writes 1 to set / hardware clears, WO write only (reads 0), CMD
//   reads the hardware value, a write gives a pulse with its data. Unmapped
//   words read 0 and ignore writes; above the map: DECERR. Clock - aclk.
//   Reset - synchronous active low aresetn. Latency - 2 clocks per write and
//   read.
// Date: 2026-10-12
module pwm_regs #(
  parameter int CHANNELS = 4  // PWM channels (1..8)
) (
  input  logic                       aclk,           // clock
  input  logic                       aresetn,        // synchronous reset, active low
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 8
  input  logic [7:0]                 s_axil_awaddr,  // AXI4-Lite
  input  logic                       s_axil_awvalid,
  output logic                       s_axil_awready,
  input  logic [31:0]                s_axil_wdata,
  input  logic [3:0]                 s_axil_wstrb,
  input  logic                       s_axil_wvalid,
  output logic                       s_axil_wready,
  output logic [1:0]                 s_axil_bresp,
  output logic                       s_axil_bvalid,
  input  logic                       s_axil_bready,
  input  logic [7:0]                 s_axil_araddr,
  input  logic                       s_axil_arvalid,
  output logic                       s_axil_arready,
  output logic [31:0]                s_axil_rdata,
  output logic [1:0]                 s_axil_rresp,
  output logic                       s_axil_rvalid,
  input  logic                       s_axil_rready,
  output logic [3-1:0]               ctrl_o,         // CTRL (RW): register value
  output logic                       ctrl_wr_o,      // CTRL: one-clock pulse at every software write
  output logic [16-1:0]              period_o,       // PERIOD (RW): register value
  output logic                       period_wr_o,    // PERIOD: one-clock pulse at every software write
  output logic [16-1:0]              prescale_o,     // PRESCALE (RW): register value
  output logic                       prescale_wr_o,  // PRESCALE: one-clock pulse at every software write
  output logic [16-1:0]              deadtime_o,     // DEADTIME (RW): register value
  output logic                       deadtime_wr_o,  // DEADTIME: one-clock pulse at every software write
  output logic [CHANNELS-1:0]        invert_o,       // INVERT (RW): register value
  output logic                       invert_wr_o,    // INVERT: one-clock pulse at every software write
  output logic [(CHANNELS)*(16)-1:0] duty_o,         // DUTY (RW): register value
  output logic [CHANNELS-1:0]        duty_wr_o       // DUTY: one-clock pulse at every software write
);
  // ---------------- register map
  localparam logic [31:0] IP_ID      = "PWMT";
  localparam logic [31:0] IP_VERSION = "1.10";
  localparam logic [31:0] IP_DATE    = 32'h10122026;   // mm/dd/yyyy, BCD
  localparam logic [7:0] A_ID = 8'h0, A_VERSION = 8'h4, A_DATE = 8'h8;
  localparam logic [7:0] A_CTRL = 8'h10;
  localparam logic [7:0] A_PERIOD = 8'h14;
  localparam logic [7:0] A_PRESCALE = 8'h18;
  localparam logic [7:0] A_DEADTIME = 8'h1C;
  localparam logic [7:0] A_INVERT = 8'h20;
  localparam logic [7:0] A_DUTY = 8'h24;   // + 4 i, i < CHANNELS
  localparam int MAP_WORDS = 17;

  logic             wr_en, rd_en, wr_err_q;
  logic [7:0]       wr_addr, rd_addr, rd_addr_q;
  logic [31:0]      wr_data, rd_data;
  logic [3:0]       wr_strb;
  axi4_lite_slave #(
    .ADDR_W(8),
    .READ_WAIT(0),
    .MAP_WORDS(MAP_WORDS)
  ) u_axil (
    .aclk(aclk),
    .aresetn(aresetn),
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .wr_en_o(wr_en),
    .wr_addr_o(wr_addr),
    .wr_data_o(wr_data),
    .wr_strb_o(wr_strb),
    .wr_err_i(wr_err_q),
    .rd_en_o(rd_en),
    .rd_addr_o(rd_addr),
    .rd_data_i(rd_data),
    .rd_valid_i(1'b1),
    .rd_err_i(1'b0)
  );
  wire [7:0] wa = {wr_addr[7:2], 2'b00};
  // byte strobes applied to the written word
  logic [31:0] wmask;
  always_comb for (int b = 0; b < 4; b++) wmask[b*8 +: 8] = {8{wr_strb[b]}};

  // ---------------- writes
  logic [31:0] ctrl_q;
  logic [31:0] period_q;
  logic [31:0] prescale_q;
  logic [31:0] deadtime_q;
  logic [31:0] invert_q;
  logic [31:0] duty_q [CHANNELS];
  always_ff @(posedge aclk) begin
    if (!aresetn) begin
      ctrl_q <= 32'h0;
      ctrl_wr_o <= 1'b0;
      period_q <= 32'h63;
      period_wr_o <= 1'b0;
      prescale_q <= 32'h0;
      prescale_wr_o <= 1'b0;
      deadtime_q <= 32'h0;
      deadtime_wr_o <= 1'b0;
      invert_q <= 32'h0;
      invert_wr_o <= 1'b0;
      for (int i = 0; i < CHANNELS; i++) duty_q[i] <= 32'h0;
      duty_wr_o <= '0;
      wr_err_q <= 1'b0;
    end else begin
      wr_err_q <= wr_en && (wa == A_ID || wa == A_VERSION || wa == A_DATE);   // writes to read-only words: SLVERR
      begin
        ctrl_wr_o <= wr_en && wa == A_CTRL;
        if (wr_en && wa == A_CTRL) ctrl_q <= (ctrl_q & ~wmask) | (wr_data & wmask);
      end
      begin
        period_wr_o <= wr_en && wa == A_PERIOD;
        if (wr_en && wa == A_PERIOD) period_q <= (period_q & ~wmask) | (wr_data & wmask);
      end
      begin
        prescale_wr_o <= wr_en && wa == A_PRESCALE;
        if (wr_en && wa == A_PRESCALE) prescale_q <= (prescale_q & ~wmask) | (wr_data & wmask);
      end
      begin
        deadtime_wr_o <= wr_en && wa == A_DEADTIME;
        if (wr_en && wa == A_DEADTIME) deadtime_q <= (deadtime_q & ~wmask) | (wr_data & wmask);
      end
      begin
        invert_wr_o <= wr_en && wa == A_INVERT;
        if (wr_en && wa == A_INVERT) invert_q <= (invert_q & ~wmask) | (wr_data & wmask);
      end
      for (int i = 0; i < CHANNELS; i++) begin
        duty_wr_o[i] <= wr_en && wa == A_DUTY + 8'(4 * i);
        if (wr_en && wa == A_DUTY + 8'(4 * i)) duty_q[i] <= (duty_q[i] & ~wmask) | (wr_data & wmask);
      end
    end
  end
  assign ctrl_o = ctrl_q[3-1:0];
  assign period_o = period_q[16-1:0];
  assign prescale_o = prescale_q[16-1:0];
  assign deadtime_o = deadtime_q[16-1:0];
  assign invert_o = invert_q[CHANNELS-1:0];
  always_comb for (int i = 0; i < CHANNELS; i++) duty_o[i*(16) +: 16] = duty_q[i][16-1:0];

  // ---------------- reads: the word addressed in the clock before
  always_ff @(posedge aclk) if (rd_en) rd_addr_q <= {rd_addr[7:2], 2'b00};
  always_comb begin
    rd_data = '0;
    case (rd_addr_q)
      A_ID:      rd_data = IP_ID;
      A_VERSION: rd_data = IP_VERSION;
      A_DATE:    rd_data = IP_DATE;
      A_CTRL: rd_data = ctrl_q;
      A_PERIOD: rd_data = period_q;
      A_PRESCALE: rd_data = prescale_q;
      A_DEADTIME: rd_data = deadtime_q;
      A_INVERT: rd_data = invert_q;
      default: begin
        for (int i = 0; i < CHANNELS; i++)
          if (rd_addr_q == A_DUTY + 8'(4 * i)) rd_data = duty_q[i];
      end
    endcase
  end
endmodule
